package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db port=5432 user=app dbname=store sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeField(f string) string {
	// Only allow known column names
	allowed := map[string]bool{"id": true, "name": true, "price": true, "sku": true, "category": true}
	if allowed[strings.ToLower(f)] {
		return f
	}
	return "id"
}

func buildSearchQuery(req SearchRequest) string {
	fields := "id, name, price, sku"
	if len(req.Fields) > 0 {
		sanitized := make([]string, 0)
		for _, f := range req.Fields {
			sanitized = append(sanitized, sanitizeField(f))
		}
		fields = strings.Join(sanitized, ", ")
	}

	// Build WHERE clause with ILIKE for text search
	where := fmt.Sprintf("WHERE name ILIKE '%%%s%%' OR sku ILIKE '%%%s%%'", req.Query, req.Query)

	// Order by clause
	orderClause := "ORDER BY id ASC"
	if req.OrderBy != "" {
		// We validate direction but the field itself uses sanitizeField
		parts := strings.SplitN(req.OrderBy, " ", 2)
		field := sanitizeField(parts[0])
		dir := "ASC"
		if len(parts) > 1 && strings.ToUpper(parts[1]) == "DESC" {
			dir = "DESC"
		}
		orderClause = fmt.Sprintf("ORDER BY %s %s", field, dir)
	}

	limit := 50
	if req.Limit > 0 && req.Limit <= 200 {
		limit = req.Limit
	}

	return fmt.Sprintf("SELECT %s FROM products %s %s LIMIT %d", fields, where, orderClause, limit)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	if len(req.Query) > 100 {
		http.Error(w, "Query too long", 400)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
